Chats.list = async (req, res) => {
	let stop;
	let { page, perPage, start, uid } = req.query;
	([page, perPage, start, uid] = [page, perPage, start, uid].map(value => isFinite(value) && parseInt(value, 10)));
	page = page || 1;
	perPage = perPage || 20;

	// start supercedes page
	if (start) {
		stop = start + perPage - 1;
	} else {
