	const { statusCode, body: configBody } = await requestAsync({
		url: `${nconf.get('url')}/api/config`,
		json: true,
		jar: jar,
		followRedirect: false,
		simple: false,
		resolveWithFullResponse: true,
	});

	if (statusCode !== 200) {
		throw new Error('[[error:invalid-response]]');
